import { expect, test } from '@playwright/test';

import { asPersona, admin } from '../e2e/personas';
import { routeMap } from '../../src/lib/routes';
import { HomePage } from '../pages/home-page';

test.describe('shell navigation journey', () => {
	asPersona(admin);
	test('journey: walks the shell by clicking its routes.ts links', async ({ page }) => {
		const entry = new HomePage(page);
		await entry.open();
		for (const name of Object.keys(routeMap)) {
			const link = page.getByRole('link', { name: routeMap[name].label }).first();
			if ((await link.count()) === 0) {
				continue;
			}
			await link.click();
			await page.waitForLoadState('domcontentloaded');
			const back = page.getByRole('link', { name: 'Refund Portal' }).first();
			if (await back.count()) {
				await back.click();
				await page.waitForLoadState('domcontentloaded');
			}
		}
		const links = page.getByRole('link');
		expect(await links.count(), 'the shell renders routes.ts links').toBeGreaterThan(0);
	});
});
